using MediatR; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using VetCommission.Application.Features.ProfessionalSpecialties; using VetCommission.WebApi.Auth; using VetCommission.WebApi.Extensions;
namespace VetCommission.WebApi.Controllers;
[ApiController,Route("api/especialidades"),Authorize(Policy=AuthorizationPolicyNames.ProfessionalSpecialtiesManage)] public sealed class ProfessionalSpecialtiesController(IMediator mediator):ControllerBase
{ [HttpGet] public async Task<IActionResult> List(CancellationToken c)=>(await mediator.Send(new ListProfessionalSpecialtiesQuery(),c)).ToActionResult(this); [HttpPost] public async Task<IActionResult> Save(SaveProfessionalSpecialtyCommand command,CancellationToken c)=>(await mediator.Send(command,c)).ToActionResult(this); [HttpPut("{id:guid}")] public async Task<IActionResult> Update(Guid id, SaveProfessionalSpecialtyRequest request,CancellationToken c)=>(await mediator.Send(new SaveProfessionalSpecialtyCommand(id,request.Name),c)).ToActionResult(this); [HttpPost("{id:guid}/ativar")] public async Task<IActionResult> Activate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProfessionalSpecialtyActiveCommand(id,true),c)).ToActionResult(this); [HttpPost("{id:guid}/inativar")] public async Task<IActionResult> Deactivate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProfessionalSpecialtyActiveCommand(id,false),c)).ToActionResult(this); public sealed record SaveProfessionalSpecialtyRequest(string Name); }
